// ruinfold-adapter.test — exercised against REAL replay fixtures (fixtures/ruinfold/*.json),
// generated by actually playing runs through the vendored ruinfold engine (scripts/play-ruinfold.mjs
// + scripts/generate-fixtures.mjs) — never hand-mocked move logs pretending to be a play session.
// The two rejected-* exceptions are explicitly hand-built and labeled as such, because they exist
// to exercise the REJECTION path, which no real client-produced log could ever hit on purpose.

import { test } from "node:test";
import assert from "node:assert/strict";
import { verify, project, id, name } from "../adapters/ruinfold.mjs";
import { dailySeed } from "../adapters/vendor/ruinfold/engine/daily.mts";
import { replay } from "../adapters/vendor/ruinfold/engine/run.mts";
import { loadFixture } from "./helpers.mjs";

test("adapter identity", () => {
  assert.equal(id, "ruinfold");
  assert.equal(name, "Ruinfold Daily");
});

test("verify() on a real played daily run agrees with directly calling the vendored replay()", async () => {
  const bundle = await loadFixture("ruinfold", "2026-08-19-daily.json");
  const v = verify(bundle);
  assert.equal(v.valid, true);

  const seed = dailySeed(bundle.date);
  const direct = replay(seed, bundle.log);
  assert.equal(direct.rejected, null);
  assert.deepEqual(v.endedAt, direct.endedAt);
  assert.equal(v.score, direct.score);
  assert.equal(v.seed, seed);
});

test("verify() ignores replayBundle.log.seed — only replayBundle.date determines the canonical seed", async () => {
  const bundle = await loadFixture("ruinfold", "2026-08-19-daily.json");
  const tampered = { date: bundle.date, log: { ...bundle.log, seed: 999999999 } };
  const honest = verify(bundle);
  const withForgedSeed = verify(tampered);
  assert.deepEqual(honest.endedAt, withForgedSeed.endedAt);
  assert.equal(honest.score, withForgedSeed.score);
  assert.equal(honest.seed, withForgedSeed.seed); // both keyed off `date`, log.seed never consulted
});

test("verify() rejects a real structurally-invalid log (bad tick/seq order)", async () => {
  const bundle = await loadFixture("ruinfold", "rejected-bad-order.json");
  const v = verify(bundle);
  assert.equal(v.valid, false);
  assert.equal(v.rejected, "bad-order");
});

test("project() on a valid verification returns TUFTE-shaped tiles with a 'now' role and no duplicate ids", async () => {
  const bundle = await loadFixture("ruinfold", "2026-08-19-daily.json");
  const v = verify(bundle);
  const p = project(bundle, v);
  assert.ok(p.title.length > 0);
  assert.ok(Array.isArray(p.tiles) && p.tiles.length > 0);
  assert.ok(p.tiles.some((t) => t.role === "now"));
  const ids = p.tiles.map((t) => t.id).filter(Boolean);
  assert.equal(new Set(ids).size, ids.length);
  for (const tile of p.tiles) assert.ok(typeof tile.html === "string" && tile.html.length > 0, `tile ${tile.id} has html`);
});

test("project() on a rejected verification still returns a renderable, honest page", async () => {
  const bundle = await loadFixture("ruinfold", "rejected-bad-order.json");
  const v = verify(bundle);
  const p = project(bundle, v);
  assert.ok(Array.isArray(p.tiles) && p.tiles.length > 0);
  assert.match(p.subtitle ?? "", /rejected/i);
});

test("a deeper real run (fixtures/ruinfold/2026-07-04-deeper.json) reports a plausible, internally-consistent score", async () => {
  const bundle = await loadFixture("ruinfold", "2026-07-04-deeper.json");
  const v = verify(bundle);
  assert.equal(v.valid, true);
  assert.ok(v.world.stats.maxFloorReached >= 0 && v.world.stats.maxFloorReached <= v.world.floorCount);
  if (v.score !== null) assert.ok(v.score >= 0);
});

test("determinism: verifying the same real bundle twice yields identical output", async () => {
  const bundle = await loadFixture("ruinfold", "2026-08-19-daily.json");
  const a = verify(bundle);
  const b = verify(bundle);
  assert.deepEqual(a, b);
});
